-- ============================================
-- LUMA — Thème 5 : MOYEN 3/3 x4 — Accompagner un proche aux urgences
-- ============================================


update scenarios set content = '{"characters": {"nurse": "l''infirmière", "doctor": "le médecin", "friend": "ton amie"}, "start_node": "n1", "nodes": {"n1": {"speaker": "nurse", "text": "Hi, what happened to bring you both in tonight?", "text_fr": "Bonjour, qu''est-ce qui vous amène tous les deux ce soir ?", "choices": [{"text": "My friend has severe stomach pain, she''s in a lot of distress.", "text_fr": "Mon amie a de fortes douleurs à l''estomac, elle est en grande détresse.", "next": "n2"}, {"text": "She''s in too much pain to speak clearly, so I''ll explain what happened.", "text_fr": "Elle a trop mal pour parler clairement, donc je vais expliquer ce qui s''est passé.", "next": "n2"}]}, "n2": {"speaker": "nurse", "text": "Okay, when did the pain start, and how severe would you say it is?", "text_fr": "D''accord, quand la douleur a-t-elle commencé, et à quel point est-elle sévère selon vous ?", "choices": [{"text": "About two hours ago, and it''s gotten progressively worse.", "text_fr": "Il y a environ deux heures, et ça a empiré progressivement.", "next": "n3"}, {"text": "Very sudden, maybe an hour ago, and it''s quite intense.", "text_fr": "Très soudain, il y a environ une heure, et c''est assez intense.", "next": "n3"}]}, "n3": {"speaker": "nurse", "text": "Has she had any nausea, vomiting, or fever?", "text_fr": "Elle a eu des nausées, des vomissements, ou de la fièvre ?", "choices": [{"text": "Yes, she vomited once about thirty minutes ago.", "text_fr": "Oui, elle a vomi une fois il y a environ trente minutes.", "next": "n4"}, {"text": "(Turn to your friend) Have you had any nausea?", "text_fr": "(Tourne-toi vers ton amie) T''as eu des nausées ?", "next": "n4b"}]}, "n4": {"speaker": "nurse", "text": "Okay, that''s helpful. Does she have any known medical conditions?", "text_fr": "D''accord, c''est utile. Elle a des conditions médicales connues ?", "choices": [{"text": "Not that I know of, she''s usually very healthy.", "text_fr": "Pas à ma connaissance, elle est généralement en bonne santé.", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "(Weakly) Yes... a little nauseous too...", "text_fr": "(Faiblement) Oui... un peu nauséeuse aussi...", "choices": [{"text": "(Relay to the nurse) She says yes, some nausea too.", "text_fr": "(Relaie à l''infirmière) Elle dit oui, un peu de nausée aussi.", "next": "n5"}]}, "n5": {"speaker": "nurse", "text": "Alright, we''ll get a doctor to see her as soon as possible. Please have a seat.", "text_fr": "D''accord, on va faire venir un médecin la voir dès que possible. Asseyez-vous s''il vous plaît.", "choices": [{"text": "Thank you, how long do you think the wait will be?", "text_fr": "Merci, combien de temps pensez-vous que l''attente sera ?", "next": "n6"}, {"text": "Thank you, I''ll stay right by her side.", "text_fr": "Merci, je reste juste à côté d''elle.", "next": "n6"}]}, "n6": {"speaker": "nurse", "text": "Given her symptoms, we''ll prioritize her — likely within 20 minutes.", "text_fr": "Vu ses symptômes, on va la prioriser — probablement dans les 20 minutes.", "choices": [{"text": "That''s reassuring, thank you for taking this seriously.", "text_fr": "C''est rassurant, merci de prendre ça au sérieux.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Twenty minutes later, a doctor calls your friend''s name.)", "text_fr": "(Vingt minutes plus tard, un médecin appelle le nom de votre amie.)", "choices": [{"text": "(Help your friend walk to the examination room.)", "text_fr": "(Aide ton amie à marcher jusqu''à la salle d''examen.)", "next": "n8"}]}, "n8": {"speaker": "doctor", "text": "I understand you''re in a lot of pain. Can your friend tell me more, since you seem more comfortable speaking?", "text_fr": "Je comprends que vous avez très mal. Votre amie peut m''en dire plus, puisque vous semblez plus à l''aise pour parler ?", "choices": [{"text": "Of course, she said the pain started on her lower right side.", "text_fr": "Bien sûr, elle a dit que la douleur a commencé sur son côté inférieur droit.", "next": "n9"}, {"text": "She mentioned it''s worse when she moves or presses on her stomach.", "text_fr": "Elle a mentionné que c''est pire quand elle bouge ou appuie sur son ventre.", "next": "n9"}]}, "n9": {"speaker": "doctor", "text": "That''s a very helpful detail — it could indicate appendicitis. We''ll run some tests right away.", "text_fr": "C''est un détail très utile — ça pourrait indiquer une appendicite. On va faire des tests tout de suite.", "choices": [{"text": "Thank you, I''m glad we came in when we did.", "text_fr": "Merci, je suis content qu''on soit venus au bon moment.", "next": "n10"}]}, "n10": {"speaker": "doctor", "text": "You did the right thing bringing her in quickly. We''ll take good care of her.", "text_fr": "Vous avez bien fait de l''amener rapidement. On va bien s''occuper d''elle.", "choices": [{"text": "Thank you so much, I''ll stay here as long as she needs me.", "text_fr": "Merci beaucoup, je reste ici aussi longtemps qu''elle a besoin de moi.", "next": "end_supported"}]}, "end_supported": {"speaker": "friend", "text": "(Weakly, but smiling) Thank you for being here with me through this.", "text_fr": "(Faiblement, mais souriante) Merci d''être là avec moi pendant tout ça.", "end": true, "ending_label": "Un ami présent dans un moment difficile 🏥💙"}}}'::jsonb, is_playable = true
where title = 'Accompagner un proche aux urgences'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
